import java.util.*;class Solution{Map<Character,String>m=new HashMap<>();Set<String>u=new HashSet<>();boolean f(String p,int i,String s,int j){if(i==p.length()||j==s.length())return i==p.length()&&j==s.length();char c=p.charAt(i);if(m.containsKey(c)){String x=m.get(c);return s.startsWith(x,j)&&f(p,i+1,s,j+x.length());}for(int e=j+1;e<=s.length();e++){String x=s.substring(j,e);if(u.contains(x))continue;m.put(c,x);u.add(x);if(f(p,i+1,s,e))return true;u.remove(x);m.remove(c);}return false;}public boolean wordPatternMatch(String p,String s){return f(p,0,s,0);}}
